// paceval | Reusable Wind-Farm Loss Functions (synthetic research demonstration)
// Original license notices for paceval_main.h / paceval_main.cpp are retained.
// External Linux paceval shared library is linked at build time, not redistributed.
//
// Model scope and independent responsibilities:
//   * Host: geometrical wind rotation, direction and layout handling, upstream
//     topology, square-sum wake deficit aggregation, physical unit checks,
//     five-MW turbine cap, statistical summaries, and reproducibility exports.
//   * paceval: 100 separately compiled algebraic/exp/sqrt wake-deficit graphs,
//     reusable cubic-power graph, and a controlled TINC diagnostic graph.
//   * Host's independent native equations and Python high-precision arithmetic
//     validate actual numerical outputs; no calibrated farm model is claimed.
//   * Wake model = Jensen-like expansion with a Gaussian lateral taper, NOT
//     the canonical Jensen top-hat model or a calibrated FLORIS/PyWake model.
#include "paceval_main.h"
#include <algorithm>
#include <array>
#include <cmath>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <numeric>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>
namespace fs=std::filesystem;
namespace {
constexpr double PI=3.141592653589793238462643383279502884;
constexpr double D=140.0, ROTOR_R=70.0, AREA=PI*ROTOR_R*ROTOR_R, CAP_MW=5.0;
void require(bool yes,const std::string&why){if(!yes)throw std::runtime_error(why);}
std::string number(double x){std::ostringstream o;o<<std::setprecision(17)<<x;return "("+o.str()+")";}
struct Settings{std::size_t variants=100,batch=128;fs::path out="out",wind_input;bool self_test=false;};
std::size_t natural(const std::string&s,std::size_t max){std::size_t pos=0;require(!s.empty()&&s[0]!='-',"bad size argument");auto x=std::stoull(s,&pos);require(pos==s.size()&&x>=1&&x<=max,"size outside allowed range");return std::size_t(x);}
Settings parse(int argc,char**argv){Settings c;for(int i=1;i<argc;++i){std::string key=argv[i];if(key=="--self-test"){c.self_test=true;continue;}require(i+1<argc,"missing option value");std::string v=argv[++i];if(key=="--variants")c.variants=natural(v,100);else if(key=="--batch")c.batch=natural(v,8192);else if(key=="--out")c.out=v;else if(key=="--wind-input")c.wind_input=v;else throw std::runtime_error("unknown option "+key);}return c;}
struct Engine{Engine(){require(paceval_InitializeLibrary(nullptr),"paceval_InitializeLibrary failed");}~Engine(){paceval_FreeLibrary();}Engine(const Engine&)=delete;Engine&operator=(const Engine&)=delete;};
struct Graph{PACEVAL_HANDLE handle=nullptr;explicit Graph(PACEVAL_HANDLE p=nullptr):handle(p){}~Graph(){if(handle)paceval_DeleteComputation(handle);}Graph(Graph&&g)noexcept:handle(g.handle){g.handle=nullptr;}Graph&operator=(Graph&&g)noexcept{if(this!=&g){if(handle)paceval_DeleteComputation(handle);handle=g.handle;g.handle=nullptr;}return *this;}Graph(const Graph&)=delete;Graph&operator=(const Graph&)=delete;};
Graph compile(const std::string&formula,unsigned long n,const char*names,bool tinc=false){Graph g(paceval_CreateComputation(formula.c_str(),n,names,tinc,nullptr));require(g.handle&&!paceval_GetIsError(g.handle),"paceval could not compile expression: "+formula);return g;}
// The C API's EXT function returns TRUE on reported *failure*, not success.
template<std::size_t N> std::vector<double> evaluate(PACEVAL_HANDLE handle,const std::vector<std::array<double,N>>&inputs,std::size_t batch){std::vector<double> values(inputs.size()),flat(batch*N),out(batch);std::vector<int> errors(batch);for(std::size_t off=0;off<inputs.size();off+=batch){std::size_t n=std::min(batch,inputs.size()-off);for(std::size_t k=0;k<n;++k)for(std::size_t j=0;j<N;++j)flat[N*k+j]=inputs[off+k][j];bool error=paceval_dGetComputationResultExt(handle,flat.data(),(unsigned long)n,out.data(),nullptr,nullptr,errors.data());require(!error,"paceval batch API returned error");for(std::size_t k=0;k<n;++k){require(errors[k]==0&&std::isfinite(out[k]),"non-finite computation output");values[off+k]=out[k];}}return values;}
struct Wind{std::size_t id;double speed,deg,rho;};
struct Turbine{std::size_t layout,id;double x,y;};
struct Variant{std::size_t id;int version=1;double ct,k,cp;std::string formula;};
struct Pair{std::size_t receiver;double dx,dy;};
using PairInput=std::array<double,2>;
using PowerInput=std::array<double,4>;
struct Workload{std::vector<Turbine> layout_turbines;std::vector<Wind> winds;std::vector<Pair> pairs;std::vector<PairInput> pair_inputs;std::vector<std::size_t> offsets;};
std::vector<Wind> default_winds(){std::vector<Wind>w;for(double speed:{6.0,8.0,10.0,12.0})for(int d=0;d<8;++d)w.push_back({w.size(),speed,double(d*45),1.225});return w;}
std::vector<Turbine> layouts(){std::vector<Turbine>v;v.reserve(24);for(std::size_t l=0;l<3;++l)for(std::size_t i=0;i<8;++i){std::size_t row=i/4,col=i%4;double x=0,y=0;if(l==0){x=col*4*D;y=(double(row)-0.5)*3*D;}else if(l==1){x=col*4*D+double(row)*2*D;y=(double(row)-0.5)*3*D+double(col%2)*0.65*D;}else{x=col*7*D;y=(double(row)-0.5)*6*D;}v.push_back({l,i,x,y});}return v;}
void wind_check(const Wind&w){require(w.id<=100000&&std::isfinite(w.speed)&&w.speed>=3&&w.speed<=30,"bad wind speed");require(std::isfinite(w.deg)&&w.deg>=0&&w.deg<360,"bad wind direction");require(std::isfinite(w.rho)&&w.rho>=0.9&&w.rho<=1.4,"bad air density");}
std::string winds_header(){return "case_id,speed_mps,direction_deg,density_kg_m3";}
std::vector<Wind> read_winds(const fs::path&p){std::ifstream f(p);require(f.good(),"cannot open wind CSV");std::string line;require(bool(std::getline(f,line))&&line==winds_header(),"wind CSV header mismatch");std::vector<Wind>w;while(std::getline(f,line)){require(!line.empty()&&std::count(line.begin(),line.end(),',')==3,"malformed wind CSV");std::stringstream in(line);std::array<std::string,4>cells;for(auto&c:cells)require(bool(std::getline(in,c,','))&&!c.empty(),"missing wind value");std::size_t pos=0;unsigned long long id=std::stoull(cells[0],&pos);require(pos==cells[0].size()&&id==w.size(),"bad wind row ordering");Wind q{w.size(),0,0,0};double*fields[3]={&q.speed,&q.deg,&q.rho};for(int j=0;j<3;++j){*fields[j]=std::stod(cells[j+1],&pos);require(pos==cells[j+1].size(),"invalid wind number");}wind_check(q);w.push_back(q);require(w.size()<=1000,"too many wind rows");}require(!w.empty(),"empty wind input");return w;}
void write_winds(const fs::path&p,const std::vector<Wind>&w){std::ofstream f(p);require(f.good(),"failed to write wind inputs");f<<std::setprecision(17)<<winds_header()<<'\n';for(auto&q:w)f<<q.id<<','<<q.speed<<','<<q.deg<<','<<q.rho<<'\n';}
Variant variant(std::size_t id){Variant m{id,1,0,0,0,""};m.ct=0.70+0.004*double(id%20);m.k=0.032+0.00075*double(id%25);m.cp=0.40+0.002*double(id%15);return m;}
std::string expression(Variant&m){const std::string ct=number(m.ct),k=number(m.k);const std::string width="("+number(ROTOR_R)+"+"+k+"*dx)";const std::string expansion="("+number(D)+"/("+number(D)+"+2*"+k+"*dx))";m.formula="(1-sqrt(1-"+ct+"))*"+expansion+"*"+expansion+"*exp((-0.5)*(dy/"+width+")*(dy/"+width+"))";return m.formula;}
double wake_native(const Variant&m,double dx,double dy){const double spread=D+2*m.k*dx, width=ROTOR_R+m.k*dx;const double d=(1-std::sqrt(1-m.ct))*std::pow(D/spread,2)*std::exp(-0.5*std::pow(dy/width,2));return d;}
double uncapped_native(double rho,double cp,double v){return 0.5*rho*AREA*cp*v*v*v/1e6;}
Workload prepare(const std::vector<Wind>&winds){Workload w;w.winds=winds;w.layout_turbines=layouts();for(std::size_t l=0;l<3;++l)for(auto&a:winds){const double angle=a.deg*PI/180.0,c=std::cos(angle),s=std::sin(angle);std::array<double,8>along{},cross{};for(std::size_t i=0;i<8;++i){auto&t=w.layout_turbines[l*8+i];along[i]=t.x*c+t.y*s;cross[i]=-t.x*s+t.y*c;}for(std::size_t receiver=0;receiver<8;++receiver){const std::size_t index=(l*winds.size()+a.id)*8+receiver;for(std::size_t upstream=0;upstream<8;++upstream){double dx=along[receiver]-along[upstream];if(dx<=D*0.1)continue;double dy=cross[receiver]-cross[upstream];w.pairs.push_back({index,dx,dy});w.pair_inputs.push_back({dx,dy});}}}return w;}
struct Results{std::vector<double> delivered,ambient,velocity,wake_outputs,raw_power;double absolute_error=0;std::size_t pair_checks=0,power_checks=0;};
Results run_variant(const Variant&m,PACEVAL_HANDLE wake_graph,PACEVAL_HANDLE power_graph,const Workload&work,std::size_t batch){const std::size_t n=3*work.winds.size()*8;Results r;r.velocity.resize(n);r.delivered.resize(n);r.ambient.resize(n);auto deficits=evaluate<2>(wake_graph,work.pair_inputs,batch);r.wake_outputs=deficits;std::vector<double>squares(n,0);for(std::size_t j=0;j<deficits.size();++j){const Pair&p=work.pairs[j];const double ref=wake_native(m,p.dx,p.dy);double err=std::abs(deficits[j]-ref);r.absolute_error=std::max(r.absolute_error,err);require(err<3e-11*(1+std::abs(ref)),"wake discrepancy at pair "+std::to_string(j));require(deficits[j]>=0&&deficits[j]<=1,"wake deficit outside [0,1]");squares[p.receiver]+=deficits[j]*deficits[j];++r.pair_checks;}std::vector<PowerInput>power_inputs;power_inputs.reserve(2*n);for(std::size_t index=0;index<n;++index){auto&a=work.winds[(index/8)%work.winds.size()];const double effective=a.speed*std::max(0.20,1-std::sqrt(squares[index]));r.velocity[index]=effective;power_inputs.push_back({a.rho,AREA,m.cp,effective});power_inputs.push_back({a.rho,AREA,m.cp,a.speed});}auto power=evaluate<4>(power_graph,power_inputs,batch);r.raw_power=power;for(std::size_t index=0;index<n;++index){double u=r.velocity[index],base=work.winds[(index/8)%work.winds.size()].speed,rho=work.winds[(index/8)%work.winds.size()].rho;const double ref=uncapped_native(rho,m.cp,u),gross=uncapped_native(rho,m.cp,base);double err=std::abs(power[2*index]-ref);r.absolute_error=std::max(r.absolute_error,err);require(err<3e-11*(1+std::abs(ref)),"power discrepancy");err=std::abs(power[2*index+1]-gross);require(err<3e-11*(1+std::abs(gross)),"gross power discrepancy");r.delivered[index]=std::min(CAP_MW,power[2*index]);r.ambient[index]=std::min(CAP_MW,power[2*index+1]);require(r.delivered[index]>=0&&r.delivered[index]<=CAP_MW&&r.ambient[index]>=r.delivered[index]-1e-10,"turbine cap or monotonicity violation");r.power_checks+=2;}return r;}
void self_test(){for(auto q:default_winds())wind_check(q);for(std::size_t id=0;id<100;++id){auto m=variant(id);require(m.ct>0&&m.ct<1&&m.cp>0&&m.cp<0.593&&m.k>0,"invalid coefficients");require(wake_native(m,200,0)>wake_native(m,200,280),"crosswind decay incorrect");require(wake_native(m,400,0)<wake_native(m,200,0),"downstream spread incorrect");}auto w=prepare(default_winds());require(w.layout_turbines.size()==24&&!w.pairs.empty(),"missing geometry");bool caught=false;try{wind_check({0,-1,40,1.225});}catch(...){caught=true;}require(caught,"invalid wind input accepted");std::cout<<"native geometry and input validation PASS\n";}
void write_layouts(const fs::path&p,const std::vector<Turbine>&v){std::ofstream f(p);require(f.good(),"layout file error");f<<std::setprecision(17)<<"layout_id,turbine_id,x_m,y_m\n";for(const auto&t:v)f<<t.layout<<','<<t.id<<','<<t.x<<','<<t.y<<'\n';}
void run(const Settings&s){fs::create_directories(s.out);auto wind=s.wind_input.empty()?default_winds():read_winds(s.wind_input);for(auto&q:wind)wind_check(q);Workload work=prepare(wind);write_winds(s.out/"wind_conditions.csv",wind);write_layouts(s.out/"layouts.csv",work.layout_turbines);Engine runtime;std::vector<Variant>models;std::vector<Graph>graphs;models.reserve(s.variants);graphs.reserve(s.variants);for(std::size_t i=0;i<s.variants;++i){models.emplace_back(variant(i));graphs.emplace_back(compile(expression(models.back()),2,"dx dy"));}Graph power=compile("0.5*rho*area*cp*v*v*v/1000000",4,"rho area cp v");
 std::ofstream m(s.out/"models.csv"),f(s.out/"farm_results.csv"),t(s.out/"selected_turbines.csv"),a(s.out/"audit_samples.csv"),u(s.out/"model_update.csv");for(auto*o:{&m,&f,&t,&a,&u}){require(o->good(),"cannot write result CSV");(*o)<<std::setprecision(17);}m<<"model_id,version,ct,wake_expansion_k,cp,expression\n";f<<"model_id,version,layout_id,wind_case,speed_mps,direction_deg,gross_power_mw,net_power_mw,wake_loss_mw,wake_loss_percent\n";t<<"model_id,layout_id,wind_case,turbine_id,effective_speed_mps,gross_power_mw,net_power_mw\n";a<<"kind,model_id,dx_m,dy_m,ct,wake_k,rho,area_m2,cp,v_mps,paceval_value,native_value\n";u<<"model_id,layout_id,wind_case,old_version,new_version,old_net_mw,new_net_mw,other_model_unchanged\n";
 std::vector<double>old17,check18;std::size_t pair_checks=0,power_checks=0;double maxerr=0;const std::size_t wc=wind.size();for(std::size_t mi=0;mi<s.variants;++mi){Variant&v=models[mi];Results out=run_variant(v,graphs[mi].handle,power.handle,work,s.batch);pair_checks+=out.pair_checks;power_checks+=out.power_checks;maxerr=std::max(maxerr,out.absolute_error);m<<v.id<<','<<v.version<<','<<v.ct<<','<<v.k<<','<<v.cp<<','<<v.formula<<'\n';if(mi==17)old17=out.delivered;if(mi==18)check18=out.delivered;
 for(std::size_t l=0;l<3;++l)for(std::size_t ci=0;ci<wc;++ci){double gross=0,net=0;for(std::size_t ti=0;ti<8;++ti){const std::size_t index=(l*wc+ci)*8+ti;gross+=out.ambient[index];net+=out.delivered[index];if(mi==0||mi==17)t<<mi<<','<<l<<','<<ci<<','<<ti<<','<<out.velocity[index]<<','<<out.ambient[index]<<','<<out.delivered[index]<<'\n';}require(net<=gross+1e-9,"net exceeds gross farm power");f<<mi<<','<<v.version<<','<<l<<','<<ci<<','<<wind[ci].speed<<','<<wind[ci].deg<<','<<gross<<','<<net<<','<<(gross-net)<<','<<(gross>0?100*(gross-net)/gross:0)<<'\n';}
 if(mi<16){for(std::size_t j=0;j<work.pairs.size();j+=std::max<std::size_t>(1,work.pairs.size()/16)){if(j>work.pairs.size()-1)break;const auto&p=work.pairs[j];const double val=out.wake_outputs[j];const double reference=wake_native(v,p.dx,p.dy);a<<"wake,"<<mi<<','<<p.dx<<','<<p.dy<<','<<v.ct<<','<<v.k<<",0,0,0,0,"<<val<<','<<reference<<'\n';}for(std::size_t i=0;i<8;++i){const std::size_t index=std::min(out.velocity.size()-1,i*11+mi);const double rho=wind[(index/8)%wc].rho;double raw=out.raw_power[2*index];const double reference=uncapped_native(rho,v.cp,out.velocity[index]);a<<"power,"<<mi<<",0,0,0,0,"<<rho<<','<<AREA<<','<<v.cp<<','<<out.velocity[index]<<','<<raw<<','<<reference<<'\n';}}
 }
 // A single, explicitly versioned graph is replaced; adjacent model 18 is rerun.
 if(s.variants>=19){Variant revised=models[17];revised.version=2;revised.ct+=0.025;auto updated=compile(expression(revised),2,"dx dy");auto r=run_variant(revised,updated.handle,power.handle,work,s.batch);auto other=run_variant(models[18],graphs[18].handle,power.handle,work,s.batch);require(other.delivered==check18,"model 18 changed while updating model 17");for(std::size_t l=0;l<3;++l)for(std::size_t ci=0;ci<wc;++ci){double old=0,now=0;for(std::size_t j=0;j<8;++j){std::size_t index=(l*wc+ci)*8+j;old+=old17[index];now+=r.delivered[index];}u<<17<<','<<l<<','<<ci<<",1,2,"<<old<<','<<now<<",true\n";}}
 // Controlled TINC diagnostic uses dyadic inputs and a smooth polynomial.
 Graph tinc=compile("cp*v*v*v",2,"cp v",true);std::ofstream z(s.out/"tinc_samples.csv");require(z.good(),"TINC CSV write error");z<<std::setprecision(17)<<"sample_id,cp,v_mps,point,raw_lower,raw_upper\n";for(std::size_t i=0;i<24;++i){std::array<double,2>x={0.375,2.0+0.125*double(i)};double lower=0,upper=0,point=paceval_dGetComputationResult(tinc.handle,x.data(),&lower,&upper);require(std::isfinite(point)&&std::isfinite(lower)&&std::isfinite(upper)&&lower<=upper,"invalid TINC result");z<<i<<','<<x[0]<<','<<x[1]<<','<<point<<','<<lower<<','<<upper<<'\n';}
 std::cout<<std::setprecision(12)<<"PASS graphs="<<graphs.size()+2<<" models="<<s.variants<<" wind_cases="<<wc<<" layouts=3 turbine_evaluations="<<s.variants*3*wc*8<<" pair_checks="<<pair_checks<<" power_checks="<<power_checks<<" max_abs_native_diff="<<maxerr<<"\n";}
}
int main(int argc,char**argv){try{auto c=parse(argc,argv);if(c.self_test)self_test();else run(c);return 0;}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<'\n';return 1;}}
